// builds the full set of CSS custom properties from just 3 user choices
function buildThemeVars(theme) {
  const { primary, secondary, bgTone } = theme;
  const bg = BG_TONES[bgTone] || BG_TONES.cream;
  const primaryText = textOn(primary);
  const secondaryText = textOn(secondary);
  return {
    "--navy": primary,
    "--navy-soft": bgTone === "dark" ? lighten(primary, 0.18) : darken(primary, 0.12),
    "--navy-text": primaryText,
    "--terracotta": secondary,
    "--terracotta-soft": mix(secondary, bg.paper, 0.78),
    "--terracotta-text": secondaryText,
    "--paper": bg.paper,
    "--paper-deep": bg.paperDeep,
    "--ink": bg.ink,
    "--line": bg.line,
    "--muted-text": bg.mutedText,
  };
}

