function activeSocialLinks(links) {
  return SOCIAL_PLATFORMS.filter(p => links[p.key]?.trim());
}

/* ---------------------------------------------------------------
   ROUTING — clean URLs (/producto/<slug>) via History API
----------------------------------------------------------------*/
// Turn a product name into a URL-safe slug, e.g. "Audífonos inalámbricos" -> "audifonos-inalambricos"
function slugify(text) {
  return String(text)
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // strip accents
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")  // non-alphanumerics -> hyphen
    .replace(/^-+|-+$/g, "")       // trim hyphens
    .slice(0, 60) || "producto";
}

// Each product's public slug: name-slug + short id suffix to guarantee uniqueness
function productSlug(product) {
  return `${slugify(product.name)}-${product.id}`;
}

// Full shareable URL for a product detail page
function productLink(product) {
  return `${window.location.origin}/producto/${productSlug(product)}`;
}

// Parse the current path. Returns { view: "catalog" | "product", slug? }
function parseRoute() {
  const path = window.location.pathname;
  const m = path.match(/^\/producto\/(.+)$/);
  if (m) return { view: "product", slug: decodeURIComponent(m[1]) };
  return { view: "catalog" };
}

// Find a product from a slug. The id is the last hyphen-separated chunk,
// so we match on that (robust even if the owner later renames the product).
function productFromSlug(slug, products) {
  if (!slug || !products) return null;
  const id = slug.split("-").pop();
  return products.find(p => p.id === id) || null;
}

// Backward-compat: old links used #product-<id>. Still honor them.
function getLegacyHashProductId() {
  const m = window.location.hash.match(/product-([a-z0-9]+)/i);
  return m ? m[1] : null;
}

// Navigate without a full page reload, then notify listeners.
function navigateTo(url) {
  window.history.pushState({}, "", url);
  window.dispatchEvent(new PopStateEvent("popstate"));
}

const seedProducts = () => ([
  {
    id: uid(), name: "Audífonos inalámbricos", category: "Electrónica",
    priceUsd: 24.99, weightLb: 0.6, photo: "", photos: [],
    desc: "Audífonos bluetooth con estuche de carga.", active: true,
  },
  {
    id: uid(), name: "Vitamina C 1000mg (120 cápsulas)", category: "Suplementos",
    priceUsd: 14.5, weightLb: 0.5, photo: "", photos: [],
    desc: "Frasco de 120 cápsulas, marca americana.", active: true,
  },
  {
    id: uid(), name: "Crema facial retinol", category: "Belleza",
    priceUsd: 19.0, weightLb: 0.4, photo: "", photos: [],
    desc: "Tratamiento nocturno anti-edad.", active: true,
  },
]);

// A product may store its images in `photos[]` (new, multi-image) or the
// legacy single `photo` string. This returns a normalized array for display.
function productPhotos(product) {
  if (Array.isArray(product.photos) && product.photos.length) return product.photos;
  if (product.photo) return [product.photo];
  return [];
}


/* ---------------------------------------------------------------
   EXCHANGE RATE HOOK
----------------------------------------------------------------*/
function useExchangeRate() {
  const [rate, setRate] = useState(null);
  const [manualOverride, setManualOverride] = useState(null);
  const [status, setStatus] = useState("loading"); // loading | live | fallback | manual

  const fetchLive = useCallback(async () => {
    setStatus("loading");
    try {
      const res = await fetch("https://api.exchangerate-api.com/v4/latest/USD");
      const data = await res.json();
      const pen = data?.rates?.PEN;
      if (pen) {
        setRate(pen);
        setStatus("live");
        return;
      }
      throw new Error("no PEN rate");
    } catch {
      setRate(FALLBACK_RATE);
      setStatus("fallback");
    }
  }, []);

  useEffect(() => {
    (async () => {
      const stored = await storageGet("settings:exchange-override", null);
      if (stored) setManualOverride(stored);
      fetchLive();
    })();
  }, [fetchLive]);

  const effectiveRate = manualOverride ?? rate ?? FALLBACK_RATE;

  const setOverride = async (val) => {
    setManualOverride(val);
    await storageSet("settings:exchange-override", val);
    setStatus(val ? "manual" : (rate ? "live" : "fallback"));
  };

  return { rate: effectiveRate, rawLiveRate: rate, status, refetch: fetchLive, manualOverride, setOverride };
}

/* ---------------------------------------------------------------
   SMALL UI PRIMITIVES
----------------------------------------------------------------*/
function Money({ usd, rate, stacked = true }) {
  const pen = (usd * rate).toFixed(2);
  if (stacked) {
    return (
      <span className="money-stack">
        <span className="money-usd">${usd.toFixed(2)}</span>
        <span className="money-pen">S/ {pen}</span>
      </span>
    );
  }
  return <span>${usd.toFixed(2)} · S/ {pen}</span>;
}

function shippingFor(weightLb, tiers) {
  const tier = tiers.find(t => weightLb <= t.maxLb) || tiers[tiers.length - 1];
  const cost = +(weightLb * tier.ratePerLb).toFixed(2);
  return { tier, cost };
}

/* ---------------------------------------------------------------
   APP
----------------------------------------------------------------*/
export default function App() {
  const [tab, setTab] = useState("catalog");
  const [products, setProducts] = useState(null);
  const [orders, setOrders] = useState(null);
  const [tiers, setTiers] = useState(DEFAULT_WEIGHT_TIERS);
  const [categories, setCategories] = useState(DEFAULT_CATEGORIES);
  const [marginPct, setMarginPct] = useState(0);
  const [unlocked, setUnlocked] = useState(false);
  const [pinAttempt, setPinAttempt] = useState("");
  const [pinError, setPinError] = useState(false);
  const [highlightId, setHighlightId] = useState(null);
  const [route, setRoute] = useState(() => parseRoute());
  // Catalog filter state lifted here so it survives navigating into a product
  // and back (lets "Back to <category>" remember where the customer was).
  // Stored as a category key ("" = all) rather than the translated label.
  const [activeCatKey, setActiveCatKey] = useState("");
  const [catalogQuery, setCatalogQuery] = useState("");
  const [lang, setLang] = useState("es");
  const [theme, setTheme] = useState(DEFAULT_THEME);
  const [links, setLinks] = useState(DEFAULT_LINKS);
  // PIN is loaded from Supabase (key "settings:adminPin"). Falls back to "dax"
  // until the remote value loads, so the owner is never locked out. To change
  // the PIN, update the value in the Supabase store_data table — there is no
  // change-PIN UI on the public site, by design (keeps it out of the source code).
  const [storePin, setStorePin] = useState("dax");
  const t = STRINGS[lang];

  const { rate, status: rateStatus, refetch, manualOverride, setOverride } = useExchangeRate();

  // load saved language + theme preference
  useEffect(() => {
    (async () => {
      const savedLang = await storageGet("settings:lang", "es");
      setLang(savedLang);
      const savedTheme = await storageGet("settings:theme", null);
      if (savedTheme) setTheme({ ...DEFAULT_THEME, ...savedTheme });
      const savedLinks = await storageGet("settings:links", null);
      if (savedLinks) setLinks({ ...DEFAULT_LINKS, ...savedLinks });
      const savedPin = await storageGet("settings:adminPin", null);
      if (savedPin) setStorePin(String(savedPin));
    })();
  }, []);

  function changeLang(next) {
    setLang(next);
    storageSet("settings:lang", next);
  }

  function updateTheme(partial) {
    setTheme(prev => {
      const next = { ...prev, ...partial };
      storageSet("settings:theme", next);
      return next;
    });
  }

  function updateLinks(partial) {
    setLinks(prev => {
      const next = { ...prev, ...partial };
      storageSet("settings:links", next);
      return next;
    });
  }

  // Add a new category (deduped, trimmed). Returns true if added.
  function addCategory(name) {
    const clean = name.trim();
    if (!clean) return false;
    if (categories.some(c => c.toLowerCase() === clean.toLowerCase())) return false;
    setCategories([...categories, clean]);
    return true;
  }

  // Delete a category. Any products in it are moved to "Otros" so nothing is
  // lost. The "Otros" bucket itself can't be deleted. If "Otros" doesn't exist
  // yet (owner removed it earlier somehow), it's re-added when needed.
  function deleteCategory(name) {
    if (name === OTHER_CATEGORY) return;
    setProducts(prev => (prev || []).map(p =>
      p.category === name ? { ...p, category: OTHER_CATEGORY } : p
    ));
    setCategories(prev => {
      let next = prev.filter(c => c !== name);
      if (!next.includes(OTHER_CATEGORY)) next = [...next, OTHER_CATEGORY];
      return next;
    });
  }

  const themeVars = useMemo(() => buildThemeVars(theme), [theme]);

  // ROUTER: keep `route` in sync with the browser URL on back/forward and
  // on programmatic navigation (navigateTo fires a popstate event).
  useEffect(() => {
    const onNav = () => {
      // Honor old #product-<id> links by redirecting to the clean URL once
      // products are available; otherwise just sync the route.
      const legacyId = getLegacyHashProductId();
      if (legacyId && products) {
        const prod = products.find(p => p.id === legacyId);
        if (prod) {
          window.history.replaceState({}, "", productLink(prod));
        }
      }
      setRoute(parseRoute());
    };
    window.addEventListener("popstate", onNav);
    return () => window.removeEventListener("popstate", onNav);
  }, [products]);

  // Once products load, resolve any legacy hash link to a clean product URL.
  useEffect(() => {
    if (!products) return;
    const legacyId = getLegacyHashProductId();
    if (legacyId) {
      const prod = products.find(p => p.id === legacyId);
      if (prod) {
        window.history.replaceState({}, "", productLink(prod));
        setRoute(parseRoute());
      }
    }
  }, [products]);

  // load
  useEffect(() => {
    (async () => {
      const p = await storageGet("catalog:products", null);
      setProducts(p ?? seedProducts());
      const o = await storageGet("orders:list", []);
      setOrders(o);
      const t = await storageGet("settings:tiers", null);
      if (t) setTiers(t);
      const m = await storageGet("settings:margin", 0);
      setMarginPct(m);
      const c = await storageGet("settings:categories", null);
      if (Array.isArray(c) && c.length) setCategories(c);
    })();
  }, []);

  useEffect(() => { if (products) storageSet("catalog:products", products); }, [products]);
  useEffect(() => { if (orders) storageSet("orders:list", orders); }, [orders]);
  useEffect(() => { storageSet("settings:tiers", tiers); }, [tiers]);
  useEffect(() => { storageSet("settings:margin", marginPct); }, [marginPct]);
  useEffect(() => { storageSet("settings:categories", categories); }, [categories]);

  const effectiveRate = rate * (1 + marginPct / 100);

  // The product currently addressed by the URL, if any.
  const routedProduct = route.view === "product"
    ? productFromSlug(route.slug, products)
    : null;

  // SEO: update the page <title> and meta description to reflect the current
  // view. Search engines and link-preview crawlers read these. We restore the
  // catalog defaults whenever we're not on a product page.
  useEffect(() => {
    const setMeta = (name, content) => {
      let el = document.querySelector(`meta[name="${name}"]`);
      if (!el) { el = document.createElement("meta"); el.setAttribute("name", name); document.head.appendChild(el); }
      el.setAttribute("content", content);
    };
    const setOG = (prop, content) => {
      let el = document.querySelector(`meta[property="${prop}"]`);
      if (!el) { el = document.createElement("meta"); el.setAttribute("property", prop); document.head.appendChild(el); }
      el.setAttribute("content", content);
    };
    if (routedProduct) {
      const priceUsd = routedProduct.priceUsd.toFixed(2);
      const title = `${routedProduct.name} — ${STORE_NAME}`;
      const desc = routedProduct.desc
        ? `${routedProduct.desc} — $${priceUsd}. ${STORE_NAME}: importación de USA a Perú.`
        : `${routedProduct.name} — $${priceUsd}. ${STORE_NAME}: importación de USA a Perú, pedido por WhatsApp.`;
      document.title = title;
      setMeta("description", desc);
      setOG("og:title", title);
      setOG("og:description", desc);
      setOG("og:type", "product");
      setOG("og:url", productLink(routedProduct));
      const imgs = productPhotos(routedProduct);
      if (imgs.length) setOG("og:image", imgs[0]);
    } else {
      const title = `${STORE_NAME} — Importación de USA a Perú`;
      const desc = `${STORE_NAME}: productos importados de Estados Unidos a Perú. Electrónica, ropa, belleza y más. Precios en dólares y soles, pedido fácil por WhatsApp.`;
      document.title = title;
      setMeta("description", desc);
      setOG("og:title", title);
      setOG("og:description", desc);
      setOG("og:type", "website");
      setOG("og:url", window.location.origin + "/");
    }
  }, [routedProduct, lang]);

  if (!products || !orders) {
    return (
      <div className="splash">
        <img src={LOGO_DATA_URI} alt={STORE_NAME} className="splash-logo" />
        <p>{t.loadingApp}…</p>
        <style>{baseStyles}</style>
      </div>
    );
  }

  return (
    <div className="app" style={themeVars}>
      <style>{baseStyles}</style>
      <Header
        rate={effectiveRate}
        rateStatus={rateStatus}
        unlocked={unlocked}
        lang={lang}
        changeLang={changeLang}
        t={t}
        links={links}
      />
      <nav className="tabs">
        <TabBtn icon={<Store size={17} />} label={t.tabCatalog} active={tab === "catalog" && route.view !== "product"} onClick={() => { setTab("catalog"); if (route.view === "product") navigateTo(window.location.origin + "/"); }} />
        {unlocked && (
          <>
            <TabBtn icon={<Pencil size={17} />} label={t.tabManage} active={tab === "manage"} onClick={() => setTab("manage")} />
            <TabBtn icon={<ClipboardList size={17} />} label={t.tabOrders} active={tab === "orders"} onClick={() => setTab("orders")} />
          </>
        )}
      </nav>

      <main className="content">
        {routedProduct && tab === "catalog" ? (
          <ProductPage
            product={routedProduct}
            rate={effectiveRate}
            tiers={tiers}
            t={t}
            lang={lang}
            links={links}
            backLabel={activeCatKey ? `${t.backTo} ${categoryLabel(activeCatKey, lang)}` : t.backToCatalog}
            onBack={() => navigateTo(window.location.origin + "/")}
          />
        ) : route.view === "product" && !routedProduct && tab === "catalog" ? (
          <ProductNotFound t={t} onBack={() => navigateTo(window.location.origin + "/")} />
        ) : (
          <>
            {tab === "catalog" && (
              <Catalog
                products={products.filter(p => p.active)}
                rate={effectiveRate} tiers={tiers} setOrders={setOrders}
                highlightId={highlightId} t={t} lang={lang} links={links}
                categories={categories}
                activeCatKey={activeCatKey} setActiveCatKey={setActiveCatKey}
                query={catalogQuery} setQuery={setCatalogQuery}
              />
            )}

            {tab === "manage" && unlocked && (
              <ManageProducts
                products={products} setProducts={setProducts}
                tiers={tiers} setTiers={setTiers}
                rate={rate} effectiveRate={effectiveRate}
                marginPct={marginPct} setMarginPct={setMarginPct}
                rateStatus={rateStatus} refetch={refetch}
                manualOverride={manualOverride} setOverride={setOverride}
                onLock={() => { setUnlocked(false); setTab("catalog"); }}
                t={t} lang={lang}
                theme={theme} updateTheme={updateTheme}
                links={links} updateLinks={updateLinks}
                categories={categories} addCategory={addCategory} deleteCategory={deleteCategory}
              />
            )}

            {tab === "orders" && unlocked && (
              <Orders orders={orders} setOrders={setOrders} rate={effectiveRate} t={t} />
            )}
          </>
        )}

        {/* Discreet owner button — inside the content box, bottom-right corner */}
        <button
          className={`owner-fab ${unlocked ? "owner-fab-open" : ""}`}
          onClick={() => {
            if (unlocked) { setUnlocked(false); setTab("catalog"); }
            else { setTab("manage"); }
          }}
          title={unlocked ? t.lock : ""}
          aria-label={unlocked ? t.lock : ""}
        >
          {unlocked ? <Unlock size={15} /> : <Lock size={15} />}
        </button>
      </main>

      {/* PIN gate as overlay when not unlocked and trying to access owner tab */}
      {!unlocked && tab === "manage" && (
        <div className="pin-overlay">
          <PinGate
            value={pinAttempt} setValue={setPinAttempt}
            error={pinError}
            t={t}
            onSubmit={() => {
              if (pinAttempt === storePin) { setUnlocked(true); setPinError(false); setPinAttempt(""); }
              else { setPinError(true); }
            }}
            onCancel={() => { setTab("catalog"); setPinAttempt(""); setPinError(false); }}
          />
        </div>
      )}
    </div>
  );
}

/* ---------------------------------------------------------------
   HEADER
----------------------------------------------------------------*/
function Header({ rate, rateStatus, lang, changeLang, t, links }) {
  const active = activeSocialLinks(links);
  return (
    <header className="hdr">
      <div className="hdr-inner">
        <div className="hdr-brand">
          <img src={LOGO_DATA_URI} alt={STORE_NAME} className="hdr-logo" />
          <div>
            <div className="hdr-title">{STORE_NAME}</div>
            <div className="hdr-sub">{t.tagline}</div>
            {active.length > 0 && (
              <div className="hdr-social">
                {active.map(p => (
                  <a key={p.key} href={p.buildUrl(links[p.key])} target="_blank" rel="noopener noreferrer"
                    className="hdr-social-btn" style={{ color: p.color }} title={p.label}>
                    {p.icon(16)}
                  </a>
                ))}
              </div>
            )}
          </div>
        </div>
        <div className="hdr-right">
          <div className="lang-toggle" role="group" aria-label="Language">
            <button className={`lang-btn ${lang === "es" ? "lang-btn-active" : ""}`} onClick={() => changeLang("es")}>ES</button>
            <button className={`lang-btn ${lang === "en" ? "lang-btn-active" : ""}`} onClick={() => changeLang("en")}>EN</button>
          </div>
          <div className="hdr-rate">
            <span className="hdr-rate-label">{t.exchangeRate}</span>
            <span className="hdr-rate-value">
              <span className={`dot dot-${rateStatus}`} title={rateStatus} />
              1 USD = S/ {rate.toFixed(3)}
            </span>
          </div>
        </div>
      </div>
    </header>
  );
}

function TabBtn({ icon, label, active, onClick }) {
  return (
    <button className={`tabbtn ${active ? "tabbtn-active" : ""}`} onClick={onClick}>
      {icon}<span>{label}</span>
    </button>
  );
}

function PinGate({ value, setValue, onSubmit, error, t, onCancel }) {
  return (
    <div className="card pingate">
      <Lock size={22} />
      <h3>{t.pinTitle}</h3>
      <p className="muted">{t.pinSub}</p>
      <input
        className="input pin-input"
        type="password"
        placeholder={t.pinPlaceholder}
        value={value}
        onChange={e => setValue(e.target.value)}
        onKeyDown={e => e.key === "Enter" && onSubmit()}
      />
      {error && <div className="error-text"><AlertCircle size={14} /> {t.pinWrong}</div>}
      <button className="btn btn-primary" onClick={onSubmit}>{t.enter}</button>
      {onCancel && <button className="btn btn-ghost" style={{ marginTop: 4 }} onClick={onCancel}>{t.cancel}</button>}
    </div>
  );
}

/* ---------------------------------------------------------------
   CATALOG (customer-facing)
----------------------------------------------------------------*/
function Catalog({ products, rate, tiers, setOrders, highlightId, t, lang, links, categories, activeCatKey, setActiveCatKey, query, setQuery }) {
  const [copiedId, setCopiedId] = useState(null);

  // if a product is deep-linked, make sure category/search don't hide it,
  // then scroll to it. Retries briefly so it works even if the card hasn't
  // painted yet (e.g. products still arriving from the network).
  useEffect(() => {
    if (!highlightId) return;
    const target = products.find(p => p.id === highlightId);
    if (!target) return;
    setActiveCatKey("");
    setQuery("");
    let tries = 0;
    const tryScroll = () => {
      const el = document.getElementById(`product-${highlightId}`);
      if (el) {
        el.scrollIntoView({ behavior: "smooth", block: "center" });
      } else if (tries < 20) {
        tries += 1;
        setTimeout(tryScroll, 100);
      }
    };
    tryScroll();
  }, [highlightId, products]);

  const filtered = useMemo(() => {
    return products.filter(p => {
      const matchesCat = !activeCatKey || p.category === activeCatKey;
      const matchesQuery = p.name.toLowerCase().includes(query.toLowerCase());
      return matchesCat && matchesQuery;
    });
  }, [products, query, activeCatKey]);

  // category chips: "" = all, then each category that actually has a product
  const usedCats = useMemo(() => {
    const present = new Set(products.map(p => p.category));
    return (categories || []).filter(c => present.has(c));
  }, [categories, products]);
  const cats = ["", ...usedCats];

  function orderViaWhatsApp(product) {
    const { tier, cost } = shippingFor(product.weightLb, tiers);
    const totalUsd = product.priceUsd + cost;
    const msg = `Hola! Quiero pedir:\n\n*${product.name}*\nPrecio: $${product.priceUsd.toFixed(2)} (S/ ${(product.priceUsd * rate).toFixed(2)})\nEnvío (${tier.label}): $${cost.toFixed(2)}\nTotal: $${totalUsd.toFixed(2)} (S/ ${(totalUsd * rate).toFixed(2)})`;
    const url = `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(msg)}`;
    window.open(url, "_blank");
  }

  function copyLink(product) {
    const link = productLink(product);
    navigator.clipboard?.writeText(link).catch(() => {});
    setCopiedId(product.id);
    setTimeout(() => setCopiedId(null), 1800);
  }

  function openProduct(product) {
    navigateTo(productLink(product));
    window.scrollTo({ top: 0 });
  }

  if (products.length === 0) {
    return (
      <div className="empty-state">
        <Package size={32} />
        <h3>{t.noProducts}</h3>
        <p className="muted">{t.noProductsSub}</p>
      </div>
    );
  }

  return (
    <div>
      <div className="search-row">
        <Search size={16} className="search-icon" />
        <input
          className="input search-input"
          placeholder={t.search}
          value={query}
          onChange={e => setQuery(e.target.value)}
        />
      </div>
      <div className="chip-row">
        {cats.map(c => (
          <button key={c || "all"} className={`chip ${activeCatKey === c ? "chip-active" : ""}`} onClick={() => setActiveCatKey(c)}>
            {c === "" ? t.all : categoryLabel(c, lang)}
          </button>
        ))}
      </div>

      {filtered.length === 0 ? (
        <p className="muted" style={{ padding: "24px 4px" }}>{t.noResults}</p>
      ) : (
        <div className="grid">
          {filtered.map(p => {
            const { tier, cost } = shippingFor(p.weightLb, tiers);
            const isHighlighted = p.id === highlightId;
            const imgs = productPhotos(p);
            return (
              <div className={`pcard ${isHighlighted ? "pcard-highlight" : ""}`} key={p.id} id={`product-${p.id}`}>
                <button className="pcard-img pcard-img-btn" onClick={() => openProduct(p)} aria-label={p.name}>
                  {imgs.length ? <img src={imgs[0]} alt={p.name} /> : <ImagePlus size={26} className="muted" />}
                  {imgs.length > 1 && (
                    <span className="pcard-photocount"><ImagePlus size={11} /> {imgs.length}</span>
                  )}
                </button>
                <div className="pcard-body">
                  <div className="pcard-cat">{categoryLabel(p.category, lang)}</div>
                  <button className="pcard-name pcard-name-btn" onClick={() => openProduct(p)}>{p.name}</button>
                  {p.desc && <div className="pcard-desc">{p.desc}</div>}
                  <Money usd={p.priceUsd} rate={rate} />
                  <div className="pcard-ship">
                    <Truck size={13} /> {t.shipping} ({tier.label.toLowerCase()}): <Money usd={cost} rate={rate} stacked={false} />
                  </div>
                  <button className="btn btn-whatsapp" onClick={() => orderViaWhatsApp(p)}>
                    <MessageCircle size={16} /> {t.orderWhatsapp}
                  </button>
                  <button className="btn btn-linkcopy" onClick={() => copyLink(p)}>
                    {copiedId === p.id ? <><Check size={14} /> {t.linkCopied}</> : <><Link2 size={14} /> {t.copyLink}</>}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}

      <ContactSection links={links} t={t} />
      <SocialFooter links={links} t={t} />
    </div>
  );
}

/* ---------------------------------------------------------------
   PRODUCT PAGE (own URL: /producto/<slug>)
----------------------------------------------------------------*/
function ProductPage({ product, rate, tiers, t, lang, links, onBack, backLabel }) {
  const [copied, setCopied] = useState(false);
  const photos = productPhotos(product);
  const { tier, cost } = shippingFor(product.weightLb, tiers);

  const waNumber = links.whatsapp?.trim()
    ? links.whatsapp.replace(/\D/g, "")
    : WHATSAPP_NUMBER;

  function order() {
    const totalUsd = product.priceUsd + cost;
    const link = productLink(product);
    const msg = `Hola! Quiero pedir:\n\n*${product.name}*\nPrecio: $${product.priceUsd.toFixed(2)} (S/ ${(product.priceUsd * rate).toFixed(2)})\nEnvío (${tier.label}): $${cost.toFixed(2)}\nTotal: $${totalUsd.toFixed(2)} (S/ ${(totalUsd * rate).toFixed(2)})\n\n${link}`;
    window.open(`https://wa.me/${waNumber}?text=${encodeURIComponent(msg)}`, "_blank");
  }

  function share() {
    const link = productLink(product);
    if (navigator.share) {
      navigator.share({ title: product.name, url: link }).catch(() => {});
    } else {
      navigator.clipboard?.writeText(link).catch(() => {});
      setCopied(true);
      setTimeout(() => setCopied(false), 1800);
    }
  }

  return (
    <div className="product-page">
      <button className="back-link" onClick={onBack}>
        <ChevronRight size={16} style={{ transform: "rotate(180deg)" }} /> {backLabel || t.backToCatalog}
      </button>

      <Gallery photos={photos} name={product.name} t={t} />

      <div className="product-info">
        <div className="product-cat">{categoryLabel(product.category, lang)}</div>
        <h1 className="product-title">{product.name}</h1>
        {product.desc && <p className="product-desc">{product.desc}</p>}

        <div className="product-price">
          <Money usd={product.priceUsd} rate={rate} />
        </div>
        <div className="product-ship">
          <Truck size={15} /> {t.shipping} ({tier.label.toLowerCase()}): <Money usd={cost} rate={rate} stacked={false} />
        </div>

        <button className="btn btn-whatsapp product-order" onClick={order}>
          <MessageCircle size={18} /> {t.orderWhatsapp}
        </button>
        <button className="btn btn-linkcopy product-share" onClick={share}>
          {copied ? <><Check size={15} /> {t.linkCopied}</> : <><Link2 size={15} /> {t.shareProduct}</>}
        </button>
      </div>

      <ContactSection links={links} t={t} />
      <SocialFooter links={links} t={t} />
    </div>
  );
}

// Swipeable / tappable image gallery. Falls back to a placeholder when empty.
function Gallery({ photos, name, t }) {
  const [idx, setIdx] = useState(0);
  if (!photos.length) {
    return (
      <div className="gallery gallery-empty">
        <ImagePlus size={40} className="muted" />
      </div>
    );
  }
  const go = (n) => setIdx((idx + n + photos.length) % photos.length);
  return (
    <div className="gallery">
      <div className="gallery-main">
        <img src={photos[idx]} alt={`${name} — ${t.photoOf} ${idx + 1}`} />
        {photos.length > 1 && (
          <>
            <button className="gallery-arrow gallery-prev" onClick={() => go(-1)} aria-label="←">
              <ChevronRight size={20} style={{ transform: "rotate(180deg)" }} />
            </button>
            <button className="gallery-arrow gallery-next" onClick={() => go(1)} aria-label="→">
              <ChevronRight size={20} />
            </button>
            <div className="gallery-counter">{idx + 1} / {photos.length}</div>
          </>
        )}
      </div>
      {photos.length > 1 && (
        <div className="gallery-thumbs">
          {photos.map((src, i) => (
            <button
              key={i}
              className={`gallery-thumb ${i === idx ? "gallery-thumb-active" : ""}`}
              onClick={() => setIdx(i)}
              aria-label={`${t.photoOf} ${i + 1}`}
            >
              <img src={src} alt="" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function ProductNotFound({ t, onBack }) {
  return (
    <div className="empty-state">
      <Package size={32} />
      <h3>{t.productNotFound}</h3>
      <p className="muted">{t.productNotFoundSub}</p>
      <button className="btn btn-linkcopy" style={{ maxWidth: 220, marginTop: 12 }} onClick={onBack}>
        <ChevronRight size={15} style={{ transform: "rotate(180deg)" }} /> {t.backToCatalog}
      </button>
    </div>
  );
}

/* ---------------------------------------------------------------
   CONTACT + SOCIAL FOOTER
----------------------------------------------------------------*/
