function ColorPicker({ value, onChange, swatches, t }) {
  const [customOpen, setCustomOpen] = useState(false);
  const [hexDraft, setHexDraft] = useState(value);
  const hsl = useMemo(() => hexToHsl(value), [value]);
  const slRef = useRef(null);
  const dragging = useRef(false);

  useEffect(() => { setHexDraft(value); }, [value]);

  function applyFromPointer(clientX, clientY) {
    const rect = slRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
    const y = Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));
    const s = x * 100;
    const l = (1 - y) * 100;
    onChange(hslToHex(hsl.h, s, l));
  }

  function handlePointerDown(e) {
    dragging.current = true;
    const point = e.touches ? e.touches[0] : e;
    applyFromPointer(point.clientX, point.clientY);
  }
  function handlePointerMove(e) {
    if (!dragging.current) return;
    const point = e.touches ? e.touches[0] : e;
    applyFromPointer(point.clientX, point.clientY);
  }
  function handlePointerUp() { dragging.current = false; }

  function handleHueChange(e) {
    onChange(hslToHex(parseFloat(e.target.value), hsl.s, hsl.l));
  }

  function commitHex() {
    if (/^#[0-9a-fA-F]{6}$/.test(hexDraft)) onChange(hexDraft);
    else setHexDraft(value);
  }

  return (
    <div>
      <div className="swatch-row">
        {swatches.map(sw => (
          <button
            key={sw}
            className={`swatch-dot ${value.toLowerCase() === sw.toLowerCase() ? "swatch-dot-active" : ""}`}
            style={{ background: sw }}
            onClick={() => { onChange(sw); setCustomOpen(false); }}
            aria-label={sw}
          />
        ))}
        <button
          className={`swatch-dot swatch-dot-custom ${customOpen ? "swatch-dot-active" : ""}`}
          onClick={() => setCustomOpen(o => !o)}
          aria-label={t.customColor}
        >
          <span className="swatch-custom-ring" style={{ background: value }} />
        </button>
      </div>

      {customOpen && (
        <div className="custom-picker">
          <div
            ref={slRef}
            className="sl-square"
            style={{ background: `linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, hsl(${hsl.h},100%,50%))` }}
            onMouseDown={e => { handlePointerDown(e); window.addEventListener("mousemove", handlePointerMove); window.addEventListener("mouseup", function up() { handlePointerUp(); window.removeEventListener("mousemove", handlePointerMove); window.removeEventListener("mouseup", up); }); }}
            onTouchStart={handlePointerDown}
            onTouchMove={handlePointerMove}
            onTouchEnd={handlePointerUp}
          >
            <div
              className="sl-thumb"
              style={{ left: `${hsl.s}%`, top: `${100 - hsl.l}%`, background: value }}
            />
          </div>
          <input
            type="range"
            className="hue-slider"
            min="0" max="360" step="1"
            value={hsl.h}
            onChange={handleHueChange}
          />
          <div className="hex-row">
            <span className="hex-prefix">#</span>
            <input
              type="text"
              className="input color-hex"
              value={hexDraft.replace("#", "")}
              onChange={e => setHexDraft("#" + e.target.value.replace(/[^0-9a-fA-F]/g, "").slice(0, 6))}
              onBlur={commitHex}
              onKeyDown={e => e.key === "Enter" && commitHex()}
              maxLength={6}
            />
          </div>
        </div>
      )}
    </div>
  );
}

